# deps/build.jl  --  Build libargon2 from source (no JLL dependency).
#
# Clones the PHC Argon2 reference implementation, compiles the shared
# library with the system C compiler + make, installs it under deps/usr,
# and emits deps/deps.jl with the absolute library path consumed by src/.

using Libdl

const UPSTREAM = "https://github.com/P-H-C/phc-winner-argon2"
const REF = get(ENV, "ARGON2_REF", "master")  # pin via env for reproducibility

const depsdir = @__DIR__
const srcdir  = joinpath(depsdir, "src", "phc-winner-argon2")
const prefix  = joinpath(depsdir, "usr")
const libdir  = joinpath(prefix, "lib")
const depsjl  = joinpath(depsdir, "deps.jl")

# --------------------------------------------------------------------------
# 1. Obtain the source (clone or update)
# --------------------------------------------------------------------------
function fetch_source()
    if !isdir(joinpath(srcdir, ".git"))
        @info "Cloning Argon2 reference source..."
        mkpath(dirname(srcdir))
        run(`git clone --depth 1 --branch $REF $UPSTREAM $srcdir`)
    else
        @info "Updating Argon2 reference source..."
        try
            run(`git -C $srcdir fetch --depth 1 origin $REF`)
            run(`git -C $srcdir checkout $REF`)
        catch
            @warn "Could not update source; using existing checkout in $srcdir"
        end
    end
end

# --------------------------------------------------------------------------
# 2. Pick a C compiler
# --------------------------------------------------------------------------
function pick_cc()
    has(v) = something(Sys.which(v), "") != ""
    get(ENV, "CC") do
        has("cc")    ? "cc"    :
        has("gcc")   ? "gcc"   :
        has("clang") ? "clang" :
        error("No C compiler (cc/gcc/clang) found on PATH. Set CC env var.")
    end
end

# --------------------------------------------------------------------------
# 3. Build the shared library
# --------------------------------------------------------------------------
function build_library()
    cc = pick_cc()
    @info "Building libargon2 with CC=$cc ..."
    make = something(Sys.which("make"), "make")
    # PREFIX shapes the macOS install_name to our local prefix.
    build_env = ("CC" => cc,)
    withenv(build_env...) do
        run(`$make -C $srcdir clean`)
        run(`$make -C $srcdir libs PREFIX=$prefix`)
    end
end

# --------------------------------------------------------------------------
# 4. Locate the freshly built shared library and stage it under deps/usr/lib
# --------------------------------------------------------------------------
function stage_library()
    mkpath(libdir)
    # Identify the shared library file produced in the source tree.
    candidates = String[]
    for f in readdir(srcdir)
        push!(candidates, joinpath(srcdir, f))
    end
    libfile = if Sys.isapple()
        f = filter(f -> occursin(r"^libargon2\..*\.dylib$", basename(f)), candidates)
        isempty(f) ? nothing : sort(f; by=filesize)[end]
    elseif Sys.islinux()
        f = filter(f -> occursin(r"^libargon2\.so(\.|$)", basename(f)), candidates)
        isempty(f) ? nothing : sort(f; by=filesize)[end]
    elseif Sys.iswindows()
        f = filter(f -> endswith(lowercase(f), ".dll"), candidates)
        isempty(f) ? nothing : sort(f; by=filesize)[end]
    else
        nothing
    end
    libfile === nothing && error("Shared library not found after build in $srcdir")
    dst = joinpath(libdir, basename(libfile))
    cp(libfile, dst; force=true)
    return dst
end

# --------------------------------------------------------------------------
# 5. Emit deps/deps.jl
# --------------------------------------------------------------------------
function write_depsjl(libpath)
    open(depsjl, "w") do io
        println(io, "# This file is GENERATED by deps/build.jl -- do not edit by hand.")
        println(io)
        println(io, "const libargon2 = ", repr(libpath))
    end
    @info "Wrote $depsjl"
end

# --------------------------------------------------------------------------
# 6. Smoke-test: dlopen + query version
# --------------------------------------------------------------------------
function verify_library(libpath)
    h = Libdl.dlopen_e(libpath)
    h == C_NULL && error("dlopen failed for $libpath")
    verptr = Libdl.dlsym_e(h, "argon2_version")
    if verptr != C_NULL
        ver = ccall(verptr, UInt32, ())
        @info "libargon2 loaded; version code = 0x$(string(ver, base=16))"
    end
    Libdl.dlclose(h)
end

# --------------------------------------------------------------------------
function main()
    isdir(prefix) && rm(prefix; recursive=true, force=true)
    fetch_source()
    build_library()
    libpath = stage_library()
    write_depsjl(libpath)
    verify_library(libpath)
    println("Argon2 build finished successfully.")
end

main()
